"""Bounded, read-only topic lookup; no SQL generated by a model."""
import json
from datetime import date, datetime, timezone, timedelta


def decode(value, default):
    return json.loads(value) if isinstance(value, (str, bytes)) else (value if value is not None else default)


def card(row, topics, *, now=None):
    from src.services.training_dates import start_visibility
    now = now or datetime.now(timezone.utc)
    before_start, start_reason = start_visibility(row, now=now)
    arrays={key:decode(row.get(key),[]) for key in ('learning_topics','tech_stacks','addresses')}
    extra=decode(row.get('additional_sections'),{})
    dates=extra.get('date_precision',{})
    deadline=row.get('application_deadline')
    valid_deadline=False
    if isinstance(deadline,datetime):
        valid_deadline=(deadline.replace(tzinfo=timezone.utc) if deadline.tzinfo is None else deadline)>now
    elif dates.get('application_deadline',{}).get('raw'):
        try:valid_deadline=date.fromisoformat(dates['application_deadline']['raw'])>=now.astimezone(timezone(timedelta(hours=9))).date()
        except (ValueError,TypeError):pass
    eligible=(row.get('recruitment_status')=='active' and extra.get('recommendation_eligible') is True and valid_deadline and before_start)
    available={v.casefold() for key in ('learning_topics','tech_stacks') for v in arrays[key] if isinstance(v,str)}
    result={key:row.get(key) for key in ('offering_id','source','source_id','source_version','source_url','recruitment_status','delivery_mode','currency','content_hash')}
    for key,limit in [('title',220),('provider_name',160),('curriculum',500),('eligibility',400),('cost_description',250)]:
        result[key]=(row.get(key) or '')[:limit]
    result.update(matched_topics=[t for t in topics if t.casefold() in available],
                  learning_topics=arrays['learning_topics'][:20],addresses=arrays['addresses'][:3],
                  tuition=str(row['tuition']) if row.get('tuition') is not None else None,
                  dates=dates,application_deadline=deadline.isoformat()+('Z' if deadline.tzinfo is None else '') if isinstance(deadline,datetime) else None,
                  recommendation_eligible=eligible,
                  start_window_eligible=before_start, start_window_reason=start_reason,
                  usage='application_candidate' if eligible else 'learning_reference')
    from src.services.training_dates import refresh_card_status
    for field in ('starts_at','ends_at'):
        value=row.get(field)
        result[field]=value.isoformat()+('Z' if value.tzinfo is None else '') if isinstance(value,datetime) else None
    from src.services.training_groups import identity
    result['cohort_name']=row.get('cohort_name')
    result['course_group_key']=identity(row,extra)
    return refresh_card_status(result,now=now)


class MySQLTrainingRepository:
    def __init__(self,connection_factory):self.factory=connection_factory

    def search(self,topics,*,exclude_ids=(),delivery_mode=None,candidates_only=False,exclude_groups=(),topic_operator="or",browse_all=False):
        if not isinstance(topics,list) or not (0 if browse_all else 1)<=len(topics)<=8 or any(not isinstance(t,str) or not 1<=len(t)<=60 for t in topics):
            raise ValueError('Invalid training topics')
        from src.services.training_navigation import training_operator
        training_operator(topic_operator)
        from src.services.training_groups import exclusions
        exclusions(exclude_groups)
        expressions=[];params=['boottent','goyong24_training']
        for topic in topics:
            expressions.append("(JSON_CONTAINS(LOWER(CAST(COALESCE(learning_topics,JSON_ARRAY()) AS CHAR CHARACTER SET utf8mb4)),JSON_QUOTE(LOWER(%s))) OR JSON_CONTAINS(LOWER(CAST(COALESCE(tech_stacks,JSON_ARRAY()) AS CHAR CHARACTER SET utf8mb4)),JSON_QUOTE(LOWER(%s))))")
            params.extend([topic,topic])
        from src.services.training_navigation import training_exclusions, training_mode
        excluded=training_exclusions(exclude_ids);training_mode(delivery_mode)
        extra=''
        if excluded:
            extra+=' AND NOT ('+' OR '.join(['(source=%s AND source_id=%s)']*len(excluded))+')'
            params.extend(v for pair in excluded for v in pair)
        if candidates_only:
            extra+=" AND (starts_at > UTC_TIMESTAMP() OR (starts_at IS NULL AND STR_TO_DATE(JSON_UNQUOTE(JSON_EXTRACT(additional_sections,'$.date_precision.starts_at.raw')),'%%Y-%%m-%%d') > DATE(UTC_TIMESTAMP() + INTERVAL 9 HOUR))) AND recruitment_status <> 'closed'"
        if delivery_mode:
            extra+=' AND delivery_mode=%s';params.append(delivery_mode)
        fields='offering_id,course_key,cohort_name,source,source_id,source_url,source_version,title,provider_name,curriculum,learning_topics,tech_stacks,eligibility,delivery_mode,addresses,tuition,currency,cost_description,recruitment_status,additional_sections,application_deadline,starts_at,ends_at,content_hash'
        conn=self.factory()
        try:
            with conn.cursor() as cur:
                cur.execute('SELECT '+fields+" FROM training_offerings WHERE source IN (%s,%s) AND recruitment_status IN ('active','unknown','closed') AND ("+(' AND ' if topic_operator=='and' else ' OR ').join(expressions or ['1=1'])+")"+extra+" ORDER BY (recruitment_status='active') DESC,offering_id DESC LIMIT 1000",params)
                rows=cur.fetchall()
                cards=[card(row,topics) for row in rows]
                if candidates_only:
                    cards=[c for c in cards if c['start_window_eligible'] and c['recruitment_status'] != 'closed']
            cards.sort(key=lambda c:(not c['recommendation_eligible'],-len(c['matched_topics']),c['offering_id']))
            from src.services.training_groups import grouped
            self.search_limited=len(rows)>=1000
            return grouped(cards,exclude_groups=exclude_groups,limit=20 if browse_all else 3)
        finally:conn.close()

    def get(self, identity):
        if not isinstance(identity,dict) or identity.get('source') not in {'boottent','goyong24_training'} or not isinstance(identity.get('source_id'),str) or not 1<=len(identity['source_id'])<=128:
            raise ValueError('Invalid training identity')
        fields='offering_id,course_key,cohort_name,source,source_id,source_url,source_version,title,provider_name,curriculum,learning_topics,tech_stacks,eligibility,preferred_conditions,benefits,selection_process,application_notes,delivery_mode,addresses,tuition,currency,cost_description,recruitment_status,additional_sections,application_deadline,starts_at,ends_at,content_hash'
        conn=self.factory()
        try:
            with conn.cursor() as cur:
                cur.execute('SELECT '+fields+' FROM training_offerings WHERE source=%s AND source_id=%s',(identity['source'],identity['source_id']))
                row=cur.fetchone()
            if not row:return None
            result=card(row,[])
            for key in ('curriculum','eligibility','preferred_conditions','benefits','selection_process','application_notes','cost_description'):
                result[key]=row.get(key) or ''
            return result
        finally:conn.close()
